films.V135BlockedGate:
// V135BlockedGate: the black SUV that locked the courtyard gate, as real greyscale photos marked by hand.
//   shot "glass": the car's front close, the marker rings its empty windshield (no number, no note)
//   shot "yard":  the courtyard from above, the marker rings the cars that stay parked instead of leaving
import React from 'react';
import {Img, staticFile, useCurrentFrame} from 'remotion';
import {cueFrame, entrance, Haptic, lead, PictureBand} from '../common';
import {spr} from '../../lib/anim';
import {OBJ} from '../../lib/layer';
import type {SceneCtx} from '../../types';
import {Ink} from '../kit/ink';
import {Card, shadow} from '../kit/p2';

type P = {
  shot?: 'glass' | 'yard';
  word?: string;
  hitAt?: number | string;
};

type Box = {x: number; y: number; w: number; h: number};
const GLASS: Box = {x: 190, y: 440, w: 700, h: 930};
const YARD: Box = {x: 140, y: 580, w: 800, h: 640};
const FILL: React.CSSProperties = {position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', filter: 'grayscale(1) contrast(1.08)'};

const Photo: React.FC<{yard: boolean; box: Box; k: number; push?: number}> = ({yard, box, k, push = 1}) => (
  <Card x={box.x} y={box.y} w={box.w} h={box.h} r={26} style={{overflow: 'hidden', boxShadow: shadow(1), opacity: k, transform: `scale(${(0.96 + 0.04 * k).toFixed(4)})`}}>
    {yard ? (
      <Img className={OBJ} src={staticFile('photos/parking-aerial-rows.jpg')} style={FILL} />
    ) : (
      <Img className={OBJ} src={staticFile('photos/rain-car-portrait.jpg')} style={{...FILL, objectPosition: '50% 0%', transformOrigin: '70% 10%', transform: `scale(${push.toFixed(4)})`}} />
    )}
  </Card>
);

const Glass: React.FC<{p: P; ctx: SceneCtx}> = ({p, ctx}) => {
  const frame = useCurrentFrame();
  const e = entrance(ctx);
  const hit = Math.max(lead(ctx) + 2, cueFrame(ctx, p.hitAt ?? 0) + 3);
  const k = spr(frame, e, 'enter');
  const g = GLASS;
  return (
    <PictureBand camera={false}>
      <Photo yard={false} box={g} k={k} push={1 + 0.05 * Math.min(1, Math.max(0, (frame - e) / Math.max(1, ctx.dur)))} />
      <Ink marks={[{kind: 'circle', box: {x: g.x + g.w * 0.44, y: g.y + g.h * 0.07, w: g.w * 0.46, h: g.h * 0.14}, at: hit, within: g}]} end={ctx.dur} />
      <Haptic kind="light" at={hit + 8} />
    </PictureBand>
  );
};

const Yard: React.FC<{p: P; ctx: SceneCtx}> = ({p, ctx}) => {
  const frame = useCurrentFrame();
  const e = entrance(ctx);
  const hit = Math.max(lead(ctx) + 6, cueFrame(ctx, p.hitAt ?? 0) + 8);
  const k = spr(frame, e, 'enter');
  const y = YARD;
  return (
    <PictureBand camera={false}>
      <Photo yard box={y} k={k} />
      <Ink
        marks={[
          {kind: 'circle', box: {x: y.x + y.w * 0.14, y: y.y + y.h * 0.2, w: y.w * 0.3, h: y.h * 0.14}, at: hit, within: y},
          {kind: 'circle', box: {x: y.x + y.w * 0.54, y: y.y + y.h * 0.58, w: y.w * 0.3, h: y.h * 0.14}, at: hit + 12, within: y},
        ]}
        end={ctx.dur}
      />
      <Haptic kind="light" at={hit + 12} />
    </PictureBand>
  );
};

export const V135BlockedGate: React.FC<{p: P; ctx: SceneCtx}> = ({p, ctx}) => (p.shot === 'yard' ? <Yard p={p} ctx={ctx} /> : <Glass p={p} ctx={ctx} />);
